function TokenBucket(options) {
  if (options == null || typeof options !== 'object') {
    throw new RangeError('Options is required');
  }

  const capacity = options.capacity;
  const refillPerSecond = options.refillPerSecond;
  const now = options.now !== undefined ? options.now : Date.now;

  // capacity kontrolü: pozitif sonlu sayı olmalı
  if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
    throw new RangeError('Capacity must be a positive finite number');
  }

  // refillPerSecond kontrolü: sayı ve negatif olmayan olmalı
  if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
    throw new RangeError('RefillPerSecond must be a non-negative finite number');
  }

  this._capacity = capacity;
  this._refillPerSecond = refillPerSecond;
  this._now = now;

  // Başlangıç zamanı
  this._startTime = now();

  // Başlangıçta kova dolu
  this._tokens = capacity;
  this._lastRefillTime = this._startTime;
}

TokenBucket.prototype = {
  tryTake(n) {
    if (arguments.length === 0) {
      n = 1;
    }

    // n kontrolü: pozitif sonlu sayı olmalı
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  },

  available() {
    return this._tokens;
  },

  msUntil(n) {
    if (arguments.length === 0) {
      n = 1;
    }

    // n kontrolü
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    // n > capacity ise veya refillPerSecond 0 ise ve yetmiyor ise Infinity
    if (n > this._capacity) {
      return Infinity;
    }

    if (this._refillPerSecond === 0) {
      // Dolum yok, mevcut jetonları kullanamazsa sonsuz bekler
      if (this._tokens < n) {
        return Infinity;
      }
      return 0;
    }

    // Geçen süre
    const currentTime = this._now();
    const elapsedSeconds = (currentTime - this._lastRefillTime) / 1000;

    // Dolum miktarı (en fazla capacity)
    const maxTokens = this._capacity;
    const filledTokens = elapsedSeconds * this._refillPerSecond;
    const currentTokens = Math.min(this._tokens + filledTokens, maxTokens);

    // Eğer jetonlarımız yeterliyse 0
    if (currentTokens >= n) {
      return 0;
    }

    // Gereken ek jeton
    const tokensNeeded = n - this._tokens;

    // Kaç saniye beklenmesi gerektiği
    const secondsNeeded = tokensNeeded / this._refillPerSecond;

    // Bekleme süresi (milisaniye olarak, yukarı yuvarlanmış)
    const msNeeded = Math.ceil(secondsNeeded * 1000);

    return msNeeded;
  }
};

module.exports = { TokenBucket };

